export const VERSION='1.0.0';
export const STORAGE_KEY='qf-studio-chapter-05-v1';
function nums(x,min=1){if(!Array.isArray(x)||x.length<min||x.some(v=>typeof v!=='number'||!Number.isFinite(v)))throw Error('Supply finite numeric observations.');return x;}
export function mean(x){nums(x);return x.reduce((a,b)=>a+b,0)/x.length;}
export function sampleSD(x){nums(x,2);if(x.every(v=>v===x[0]))return 0;const m=mean(x);return Math.sqrt(x.reduce((s,v)=>s+(v-m)**2,0)/(x.length-1));}
export function wealth(x,start=100){nums(x);if(x.some(v=>v<=-100)||!Number.isFinite(start)||start<=0)throw Error('Use a positive initial value and returns above −100%.');let w=start;return [w,...x.map(v=>(w*=1+v/100))];}
const q=(id,title,answer,hint,critical=false,type='number')=>({id,title,answer,hint,critical,type,tolerance:.011});

export const STEPS=[['start','Set up your dashboard',10],['spread','Measure monthly spread',25],['drawdown','Follow the wealth path',25],['sharpe','Use a declared Sharpe',25],['benchmark','Compare like with like',25],['lab','Change the risk-free input',40],['assessment','Independent transfer',20],['finish','Save a risk card',10]];
export const DATA=[{date:'2025-01',a:5,b:2},{date:'2025-02',a:-4,b:-1},{date:'2025-03',a:3,b:2},{date:'2025-04',a:-2,b:0},{date:'2025-05',a:4,b:3},{date:'2025-06',a:1,b:1}];
export const A=DATA.map(r=>r.a),B=DATA.map(r=>r.b);
export function drawdown(x){const w=wealth(x);let peak=w[0],maximum=0;const rows=w.map((value,i)=>{peak=Math.max(peak,value);const dd=(value/peak-1)*100;maximum=Math.max(maximum,-dd);return {month:i,wealth:value,peak,drawdown:dd};});return {maximum,rows};}
export function monthlyRF(annualPct){if(typeof annualPct!=='number'||!Number.isFinite(annualPct)||annualPct<=-100)throw Error('Annual effective risk-free rate must exceed −100%.');return 100*((1+annualPct/100)**(1/12)-1);}
export function sharpe(x,annualPct=0){nums(x,2);const rf=monthlyRF(annualPct),excess=x.map(v=>v-rf),sd=sampleSD(excess);return sd===0?null:Math.sqrt(12)*mean(excess)/sd;}
export function annualVol(x){return sampleSD(x)*Math.sqrt(12);}
export const DEFAULT_PARAMETER=0;
export function experiment(parameter=0){if(typeof parameter!=='number'||!Number.isFinite(parameter)||parameter<0||parameter>12)throw Error('Use an annual effective risk-free input from 0 to 12%.');return {parameter,rf:monthlyRF(parameter),vol:annualVol(A),sharpe:sharpe(A,parameter),drawdown:drawdown(A).maximum,hand:A[0]-monthlyRF(parameter),rows:drawdown(A).rows};}
export const PRACTICE={spread:[q('v1','For monthly returns [−2,0,2]%, sample SD in percentage points?',2,'Mean 0; squared deviations sum 8; divide by n−1=2, then square root.'),q('v2','Annualised SD for that sample under square-root-of-time scaling (percentage points)?',2*Math.sqrt(12),'Multiply 2 by √12, not 12. This scaling assumes independent, identically distributed monthly returns.')],drawdown:[q('d1','Initial wealth 100; first month −20%, then +25%. Maximum drawdown as a positive loss magnitude (%)?',20,'Include initial 100 as a peak: wealth 100→80→100, worst loss from peak is 20%.'),q('d2','New path +25%, then −20%. Final wealth from 100?',100,'100×1.25×.8=100. Ending wealth hides the 20% drawdown from 125.')],sharpe:[q('s1','Monthly returns [−1,1,3]%, monthly risk-free 0%. Annualised Sharpe under the declared scaling?',Math.sqrt(12)/2,'Mean excess=1 percentage point, sample SD=2; multiply the ratio .5 by √12.'),q('s2','A constant excess-return series has zero sample SD. Enter 1 for Sharpe=0; 2 for undefined.',2,'The denominator is zero; report undefined rather than a zero Sharpe.',true,'choice')],benchmark:[q('b1','Portfolio wealth 100→108; matching-date benchmark 100→105. Difference in total-return percentage points?',3,'8%−5%=3 percentage points; this is not a 3% ratio of ending values.'),q('b2','For comparing six monthly results, enter 1 for a benchmark over those same dates and same currency/return basis; 2 for its best twelve months.',1,'Keep dates, frequency, currency, distributions and cost basis comparable.',true,'choice')]};
export const ASSESSMENTS=[q('a1','New sample [−3,0,3]%. Sample monthly SD (percentage points)?',3,'Squared deviations sum 18; divide by 2; square root 3.'),q('a2','Annualised SD of that sample using √12 (percentage points)?',3*Math.sqrt(12),'3×√12≈10.3923; assumptions must accompany the result.'),q('a3','Initial wealth 100; returns [−10,10]%. Maximum drawdown as a positive magnitude (%)?',10,'100→90→99. Initial wealth belongs in the peak sequence.',true),q('a4','For monthly excess returns [0,2,4]%, annualised Sharpe using sample SD?',Math.sqrt(12),'Mean=2; sample SD=2; ratio1×√12.'),q('a5','If every monthly excess return is 2%, enter 1 for undefined Sharpe; 2 for Sharpe=2.',1,'A zero denominator makes the ratio undefined.',true,'choice'),q('a6','Annual effective risk-free rate 12%. Matching effective monthly rate (%)?',monthlyRF(12),'100×(1.12^(1/12)−1), not 12/12.',true),q('a7','New portfolio total return 6%, benchmark 8%, same dates. Difference in percentage points?',-2,'6−8=−2. Underperformance is a valid reported result.'),q('a8','Enter 1 if six hypothetical months prove future outperformance; 2 if conclusions are conditional on sample, benchmark and assumptions.',2,'The sample is invented and tiny; neither risk metric nor relative result guarantees future performance.',true,'choice')];

export function check(q,raw){if(typeof raw==='boolean'||raw===null||String(raw??'').trim()==='')return false;const n=Number(raw);return Number.isFinite(n)&&Math.abs(n-q.answer)<=(q.type==='choice'?0:q.tolerance);}
export function grade(answers){const details=ASSESSMENTS.map(q=>({id:q.id,correct:check(q,answers[q.id]),critical:q.critical}));const score=details.filter(d=>d.correct).length;return {score,passed:score>=7&&details.filter(d=>d.critical).every(d=>d.correct),details};}
export const freshState=()=>({version:VERSION,fields:{},done:{},checked:{},practiceAttempts:[],runs:[],attempts:[]});
export function invalidate(s,id){for(const [step,qs]of Object.entries(PRACTICE))if(qs.some(q=>q.id===id)||id===step+'Reflection'||id===step+'Criteria'){delete s.done[step];delete s.checked[id];}if(id.startsWith('quiz-')||id==='revision'){delete s.done.assessment;s.fields.quizDirty='yes';}if(['prediction','parameter','hand','labReflection','labCriteria'].includes(id)){delete s.done.lab;if(id==='hand')s.fields.handVerified='';}if(id.startsWith('card'))delete s.done.finish;if(id==='setup')delete s.done.start;}
export function labEvidence(s){const run=s.runs.at(-1);return !!run&&(s.fields.parameter===undefined||s.fields.parameter.trim()!=='')&&run.prediction===s.fields.prediction&&run.parameter===Number(s.fields.parameter??DEFAULT_PARAMETER)&&new Set(s.runs.map(r=>r.parameter)).size>=2&&check({answer:run.hand,tolerance:.011},s.fields.hand)&&s.fields.handVerified==='yes'&&(s.fields.labReflection||'').trim().length>=50&&s.fields.labCriteria==='yes';}
export function restoreState(raw){try{const s=JSON.parse(raw),record=v=>v&&typeof v==='object'&&!Array.isArray(v);if(s?.version!==VERSION||!record(s.fields)||Object.values(s.fields).some(v=>typeof v!=='string')||!record(s.done)||!record(s.checked)||Object.values(s.done).some(v=>typeof v!=='boolean')||Object.values(s.checked).some(v=>typeof v!=='boolean')||!Array.isArray(s.runs)||!Array.isArray(s.attempts))throw Error();const restored={...freshState(),fields:s.fields,practiceAttempts:(Array.isArray(s.practiceAttempts)?s.practiceAttempts:[]).filter(a=>record(a)&&typeof a.id==='string'&&typeof a.raw==='string'&&typeof a.correct==='boolean'&&typeof a.time==='string'),runs:s.runs.map(r=>{if(typeof r.prediction!=='string'||typeof r.time!=='string')throw Error();return {...experiment(r.parameter),prediction:r.prediction,time:r.time};}),attempts:s.attempts.map(a=>{if(!record(a.answers)||Object.values(a.answers).some(v=>typeof v!=='string')||typeof a.time!=='string'||(a.revision!==undefined&&typeof a.revision!=='string'))throw Error();return {...a,...grade(a.answers)};})};for(const[step,qs]of Object.entries(PRACTICE)){for(const q of qs)if(s.checked[q.id]===true&&check(q,s.fields[q.id]))restored.checked[q.id]=true;if(qs.every(q=>restored.checked[q.id])&&(s.fields[step+'Reflection']||'').trim().length>=30&&s.fields[step+'Criteria']==='yes')restored.done[step]=true;}if(s.fields.setup==='yes')restored.done.start=true;const latest=restored.attempts.at(-1);if(latest?.passed&&s.fields.quizDirty!=='yes'&&latest.revision?.length>=30&&ASSESSMENTS.every(q=>latest.answers[q.id]===s.fields['quiz-'+q.id]))restored.done.assessment=true;if(['cardMethod','cardCheck','cardLimit'].every(k=>(s.fields[k]||'').trim().length>=30)&&s.fields.cardCriteria==='yes')restored.done.finish=true;if(labEvidence(restored))restored.done.lab=true;return restored;}catch{return freshState();}}
